1	import type {ChatSession} from '../types/session.js';
2	import type {ToolRegistry, ToolContext, ToolResponse} from './tools/registry.js';
3	import type {
4	  AIProvider,
5	  Message,
6	  MessageChunk,
7	  SendMessageParams,
8	  ToolCall,
9	  ToolResultContent,
10	  TurnUsageMetadata,
11	  UsageMetadata,
12	} from '../types/ai.js';
13	import type {OutgoingMessage} from '../types/messages.js';
14	import type {PromptBuilder, PromptBuilderOptions} from '../infrastructure/builders/promptBuilder.js';
15	import type {SessionStore} from '../types/sessionStore.js';
16	import {toMessages, createContextConfig} from './conversationContext.js';
17	import type {ContextConfig} from './conversationContext.js';
18	import {
19	  shouldContinueToolLoop,
20	  collectText,
21	  buildToolCallMessages,
22	  collectToolCalls,
23	  extractStopReason,
24	  extractUsage,
25	  accumulateUsage,
26	} from './orchestratorHelpers.js';
27	import {appendEntry, commitStreamingEntries} from './entryMutations.js';
28	import {log} from '../shared/logger.js';
29	
30	const DEFAULT_MAX_TOOL_ROUNDS = 5;
31	
32	export interface OrchestratorHooks {
33	  beforeSession?: (session: ChatSession) => Promise<void>;
34	  afterSession?: (session: ChatSession) => Promise<void>;
35	  beforeUserInput?: (session: ChatSession, userMessage: string) => Promise<string>;
36	  afterUserInput?: (session: ChatSession, userMessage: string) => Promise<void>;
37	  beforeModelResponse?: (session: ChatSession, systemPrompt: string) => Promise<string>;
38	  afterModelResponse?: (session: ChatSession, responseText: string, usage?: TurnUsageMetadata) => Promise<void>;
39	  onError?: (session: ChatSession, error: Error) => Promise<void>;
40	  /** The supported seam for an EU AI Act Art. 14 human-oversight control: fires before each known tool's executor, and a returned ToolResponse replaces the call (see docs/adding-a-tool.md); it receives the model's raw tool input and, through session, the caller's authHeaders, so a policy that logs either logs personal data and credential material; the engine asserts nothing about any policy installed here. */
41	  beforeToolCall?: (session: ChatSession, call: ToolCall) => Promise<ToolResponse | undefined>;
42	  /** Fires when the model asks for a tool round the budget refuses, after the last provider call and before afterModelResponse; a returned string reaches the user as the turn's closing text, and the engine writes none of its own (see specs/hal-engine-tool-budget/spec.md). */
43	  onToolBudgetExhausted?: (session: ChatSession, budget: ToolBudgetInfo) => Promise<string | undefined>;
44	}
45	
46	export interface ToolBudgetInfo {
47	  maxToolRounds: number;
48	  requestedTools: string[];
49	}
50	
51	type BeforeToolCall = NonNullable<OrchestratorHooks['beforeToolCall']>;
52	type OnToolBudgetExhausted = NonNullable<OrchestratorHooks['onToolBudgetExhausted']>;
53	
54	export const TOOL_BUDGET_EXHAUSTED = 'tool_budget_exhausted';
55	
56	export interface ChatOrchestrator {
57	  processMessage(session: ChatSession): Promise<string>;
58	  processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk>;
59	}
60	
61	export interface ChatOrchestratorOptions {
62	  maxToolRounds?: number;
63	  contextConfig?: Partial<ContextConfig>;
64	  promptBuilderOptions?: PromptBuilderOptions;
65	  hooks?: OrchestratorHooks;
66	  sessionStore?: SessionStore;
67	}
68	
69	interface ToolExecutionResult {
70	  clientMessages: OutgoingMessage[];
71	  suppressOutput: boolean;
72	}
73	export function createChatOrchestrator(
74	  provider: AIProvider,
75	  promptBuilder: PromptBuilder,
76	  toolRegistry?: ToolRegistry,
77	  options?: ChatOrchestratorOptions
78	): ChatOrchestrator {
79	  const maxToolRounds = normalizeToolRounds(options?.maxToolRounds);
80	  const contextConfig = createContextConfig(options?.contextConfig);
81	  const toolInstructions = toolRegistry?.getPromptInstructions();
82	  const baseSystemPrompt = promptBuilder.build({...options?.promptBuilderOptions, toolInstructions});
83	  const tools = toolRegistry?.getDefinitions();
84	  const hooks = options?.hooks;
85	  const sessionStore = options?.sessionStore;
86	
87	  return {
88	    async processMessage(session: ChatSession): Promise<string> {
89	      return collectText(this.processMessageStream(session));
90	    },
91	
92	    async *processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk> {
93	      try {
94	        if (hooks?.beforeSession) await hooks.beforeSession(session);
95	
96	        let userMessage = lastUserContent(session);
97	
98	        if (hooks?.beforeUserInput) {
99	          userMessage = await rewriteUserMessage(session, userMessage, hooks.beforeUserInput);
100	        }
101	
102	        if (hooks?.afterUserInput) await hooks.afterUserInput(session, userMessage);
103	
104	        const systemPrompt = hooks?.beforeModelResponse
105	          ? await hooks.beforeModelResponse(session, baseSystemPrompt)
106	          : baseSystemPrompt;
107	
108	        const messages: Message[] = toMessages(session.entries, contextConfig);
109	        let lastUsage: UsageMetadata | undefined;
110	        let responseText = '';
111	
112	        // Bounded by the budget gate below, not the header: maxToolRounds executed rounds, maxToolRounds + 1 provider calls.
113	        for (let round = 0; ; round++) {
114	          log.info('orchestrator', 'starting round', {round});
115	          const pendingToolCalls: ToolCall[] = [];
116	
117	          const outcome = yield* streamRound(provider, {messages, systemPrompt, tools}, pendingToolCalls);
118	          responseText += outcome.text;
119	          lastUsage = accumulateUsage(lastUsage, outcome.usage);
120	
121	          if (!shouldContinueToolLoop(outcome.stopReason, pendingToolCalls, toolRegistry)) break;
122	          if (budgetSpent(round, maxToolRounds, pendingToolCalls)) {
123	            const budget = {maxToolRounds, requestedTools: pendingToolCalls.map(tc => tc.name)};
124	            responseText += yield* closeExhaustedTurn(session, budget, hooks?.onToolBudgetExhausted);
125	            break;
126	          }
127	
128	          log.info('orchestrator', 'executing tools', {tools: pendingToolCalls.map(tc => tc.name)});
129	          const {clientMessages, suppressOutput} = await executeToolCalls(
130	            pendingToolCalls,
131	            messages,
132	            session,
133	            toolCallRunner(toolRegistry!, session, hooks?.beforeToolCall)
134	          );
135	          log.info('orchestrator', 'tool execution complete', {
136	            clientMessageCount: clientMessages.length,
137	            clientMessageTypes: clientMessages.map(m => m.type),
138	            suppressOutput,
139	          });
140	
141	          if (clientMessages.length > 0) {
142	            yield {type: 'tool_result' as const, clientMessages};
143	          }
144	
145	          if (suppressOutput) {
146	            yield {type: 'suppress_output' as const};
147	          }
148	        }
149	
150	        if (hooks?.afterModelResponse) await hooks.afterModelResponse(session, responseText, lastUsage);
151	      } catch (error) {
152	        if (hooks?.onError && error instanceof Error) {
153	          await hooks.onError(session, error);
154	        }
155	        throw error;
156	      } finally {
157	        // Before both: a provider that threw mid-stream leaves an entry open, and nothing should persist it that way.
158	        commitStreamingEntries(session);
159	        try {
160	          if (hooks?.afterSession) await hooks.afterSession(session);
161	        } finally {
162	          await saveSession(sessionStore, session);
163	        }
164	      }
165	    },
166	  };
167	}
168	
169	// A negative budget means no tool rounds; a non-finite one, NaN included, falls back to the default rather than never ending.
170	function normalizeToolRounds(value: number | undefined): number {
171	  if (value === undefined || !Number.isFinite(value)) return DEFAULT_MAX_TOOL_ROUNDS;
172	  return Math.max(0, Math.floor(value));
173	}
174	
175	// Gates execution, not the provider call: a round nobody can read is never run, and the call that read the last one already has.
176	function budgetSpent(round: number, maxToolRounds: number, pendingToolCalls: ToolCall[]): boolean {
177	  if (round < maxToolRounds) return false;
178	  log.warn('orchestrator', 'tool budget exhausted', {
179	    maxToolRounds,
180	    requestedTools: pendingToolCalls.map(tc => tc.name),
181	  });
182	  return true;
183	}
184	
185	// The stop always follows the text: the round's own stop already committed its entry, and a bare text chunk would open one never committed.
186	async function* closeExhaustedTurn(
187	  session: ChatSession,
188	  budget: ToolBudgetInfo,
189	  hook?: OnToolBudgetExhausted
190	): AsyncGenerator<MessageChunk, string> {
191	  const sentence = (hook ? await hook(session, budget) : undefined) ?? '';
192	  if (sentence !== '') yield {type: 'text', text: sentence};
193	  yield {type: 'stop', stopReason: TOOL_BUDGET_EXHAUSTED};
194	  return sentence;
195	}
196	
197	interface RoundOutcome {
198	  stopReason: string;
199	  text: string;
200	  usage?: UsageMetadata;
201	}
202	
203	// `yield*` in the caller evaluates to this return, so the round's totals come back as data.
204	async function* streamRound(
205	  provider: AIProvider,
206	  request: SendMessageParams,
207	  pendingToolCalls: ToolCall[]
208	): AsyncGenerator<MessageChunk, RoundOutcome> {
209	  let stopReason = '';
210	  let text = '';
211	  let usage: UsageMetadata | undefined;
212	
213	  for await (const chunk of provider.sendMessage(request)) {
214	    yield chunk;
215	    collectToolCalls(chunk, pendingToolCalls);
216	    stopReason = extractStopReason(chunk) ?? stopReason;
217	    usage = extractUsage(chunk) ?? usage;
218	    if (chunk.type === 'text') text += chunk.text;
219	  }
220	
221	  return {stopReason, text, usage};
222	}
223	
224	// A changed message is also written back to the session's last user entry.
225	async function rewriteUserMessage(
226	  session: ChatSession,
227	  userMessage: string,
228	  hook: (session: ChatSession, userMessage: string) => Promise<string>
229	): Promise<string> {
230	  const modified = await hook(session, userMessage);
231	  if (modified === userMessage) return userMessage;
232	
233	  updateLastUserContent(session, modified);
234	  return modified;
235	}
236	
237	function lastUserContent(session: ChatSession): string {
238	  for (let i = session.entries.length - 1; i >= 0; i--) {
239	    const entry = session.entries[i];
240	    if (entry.role === 'user') return entry.content;
241	  }
242	  return '';
243	}
244	
245	function updateLastUserContent(session: ChatSession, content: string): void {
246	  for (let i = session.entries.length - 1; i >= 0; i--) {
247	    const entry = session.entries[i];
248	    if (entry.role === 'user') {
249	      entry.content = content;
250	      return;
251	    }
252	  }
253	}
254	
255	// One runner per round: the policy sees each known call before its executor, and an unknown name keeps the registry's own path.
256	function toolCallRunner(toolRegistry: ToolRegistry, session: ChatSession, beforeToolCall?: BeforeToolCall) {
257	  const context: ToolContext = {
258	    userId: session.userId,
259	    sessionId: session.sessionId,
260	    workspaceId: session.workspaceId,
261	    authHeaders: session.authHeaders,
262	  };
263	
264	  return async (tc: ToolCall): Promise<ToolResponse> => {
265	    const declined =
266	      beforeToolCall && toolRegistry.has(tc.name) ? await consultPolicy(beforeToolCall, session, tc) : undefined;
267	    return declined ?? toolRegistry.execute(tc.name, tc.input, context);
268	  };
269	}
270	
271	// A throwing policy declines its call rather than failing the turn: every tool_use must still be answered.
272	async function consultPolicy(
273	  policy: BeforeToolCall,
274	  session: ChatSession,
275	  tc: ToolCall
276	): Promise<ToolResponse | undefined> {
277	  try {
278	    return await policy(session, tc);
279	  } catch (error) {
280	    log.warn('orchestrator', 'beforeToolCall threw, so the call is declined', {
281	      tool: tc.name,
282	      errorType: error instanceof Error ? error.name : typeof error,
283	    });
284	    return {result: `The ${tc.name} call was declined and not performed.`};
285	  }
286	}
287	
288	async function executeToolCalls(
289	  pendingToolCalls: ToolCall[],
290	  messages: Message[],
291	  session: ChatSession,
292	  runToolCall: (tc: ToolCall) => Promise<ToolResponse>
293	): Promise<ToolExecutionResult> {
294	  messages.push(buildToolCallMessages(pendingToolCalls));
295	
296	  const responses = await Promise.all(
297	    pendingToolCalls.map(async tc => {
298	      const response = await runToolCall(tc);
299	      return {tc, response};
300	    })
301	  );
302	
303	  const toolResults: ToolResultContent[] = responses.map(({tc, response}) => ({
304	    type: 'tool_result' as const,
305	    toolUseId: tc.id,
306	    content: response.result,
307	  }));
308	  messages.push({role: 'user', content: toolResults});
309	
310	  const rawClientMessages = responses.flatMap(({response}) => response.clientMessages ?? []);
311	
312	  return {
313	    clientMessages: assignEntryIndices(rawClientMessages, session),
314	    suppressOutput: responses.some(({response}) => response.suppressAssistantResponse === true),
315	  };
316	}
317	
318	function assignEntryIndices(clientMessages: OutgoingMessage[], session: ChatSession): OutgoingMessage[] {
319	  return clientMessages.map(msg => {
320	    if (msg.type !== 'entry_upsert') return msg;
321	    const index = appendEntry(session, msg.entry);
322	    return {...msg, index};
323	  });
324	}
325	
326	// A store outage is not a reason to fail the turn the customer already received.
327	async function saveSession(store: SessionStore | undefined, session: ChatSession): Promise<void> {
328	  if (!store?.save) return;
329	
330	  try {
331	    await store.save(session);
332	  } catch (error) {
333	    const message = error instanceof Error ? error.message : String(error);
334	    log.error('orchestrator', 'session save failed', {sessionId: session.sessionId, error: message});
335	  }
336	}
